FuncDef.Code:
// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
//
// Code by luk77 based on:
// (Dual polyhedrons)
// https://en.wikipedia.org/wiki/Deltoidal_icositetrahedron
// https://en.wikipedia.org/wiki/Rhombicuboctahedron
float hgsdfRhombicuboctahedronSoft(vec3 p, float r, float e)
{
    const float a = 0.5 * sqrt(2.0);
    const float b = (2.0 * sqrt(2.0) + 1.0) / 7.0;

    const vec3 v0 = vec3( 1,    0,    0);
    const vec3 v1 = vec3(-1,    0,    0);
    const vec3 v2 = vec3( 0,    1,    0);
    const vec3 v3 = vec3( 0,   -1,    0);
    const vec3 v4 = vec3( 0,    0,    1);
    const vec3 v5 = vec3( 0,    0,   -1);
    const vec3 v6 = vec3( 0,    a,    a);
    const vec3 v7 = vec3( 0,    a,   -a);
    const vec3 v8 = vec3( 0,   -a,    a);
    const vec3 v9 = vec3( 0,   -a,   -a);
    const vec3 v10= vec3( a,    0,    a);
    const vec3 v11= vec3( a,    0,   -a);
    const vec3 v12= vec3(-a,    0,    a);
    const vec3 v13= vec3(-a,    0,   -a);
    const vec3 v14= vec3( a,    a,    0);
    const vec3 v15= vec3( a,   -a,    0);
    const vec3 v16= vec3(-a,    a,    0);
    const vec3 v17= vec3(-a,   -a,    0);
    const vec3 v18= vec3( b,    b,    b);
    const vec3 v19= vec3( b,    b,   -b);
    const vec3 v20= vec3( b,   -b,    b);
    const vec3 v21= vec3( b,   -b,   -b);
    const vec3 v22= vec3(-b,    b,    b);
    const vec3 v23= vec3(-b,    b,   -b);
    const vec3 v24= vec3(-b,   -b,    b);
    const vec3 v25= vec3(-b,   -b,   -b);

    float d = 0.0;

    d += pow(abs(dot(p, v0 )), e);
    d += pow(abs(dot(p, v1 )), e);
    d += pow(abs(dot(p, v2 )), e);
    d += pow(abs(dot(p, v3 )), e);
    d += pow(abs(dot(p, v4 )), e);
    d += pow(abs(dot(p, v5 )), e);
    d += pow(abs(dot(p, v6 )), e);
    d += pow(abs(dot(p, v7 )), e);
    d += pow(abs(dot(p, v8 )), e);
    d += pow(abs(dot(p, v9 )), e);
    d += pow(abs(dot(p, v10)), e);
    d += pow(abs(dot(p, v11)), e);
    d += pow(abs(dot(p, v12)), e);
    d += pow(abs(dot(p, v13)), e);
    d += pow(abs(dot(p, v14)), e);
    d += pow(abs(dot(p, v15)), e);
    d += pow(abs(dot(p, v16)), e);
    d += pow(abs(dot(p, v17)), e);
    d += pow(abs(dot(p, v18)), e);
    d += pow(abs(dot(p, v19)), e);
    d += pow(abs(dot(p, v20)), e);
    d += pow(abs(dot(p, v21)), e);
    d += pow(abs(dot(p, v22)), e);
    d += pow(abs(dot(p, v23)), e);
    d += pow(abs(dot(p, v24)), e);
    d += pow(abs(dot(p, v25)), e);

    return pow(d, 1./e) - r;
}
